<?php declare(strict_types=1); ?>
<?php if($errors): ?><div class="alert"><?= kd_e(implode(' ',$errors)) ?></div><?php endif; ?><?php if($success): ?><div class="settings-success"><?= kd_e($success) ?></div><?php endif; ?>
<div class="marketplace-grid"><section class="panel customer-form-panel"><h3>Etkinlik oluştur</h3><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="create"><label>Başlık<input name="title" maxlength="190" required></label><label>Tür<select name="event_type"><?php foreach(['meeting'=>'Toplantı','appointment'=>'Randevu','delivery'=>'Teslimat','service'=>'Servis','reminder'=>'Hatırlatma','other'=>'Diğer'] as $k=>$v): ?><option value="<?= $k ?>"><?= $v ?></option><?php endforeach; ?></select></label><label>Başlangıç<input type="datetime-local" name="start_at" required value="<?= date('Y-m-d\\TH:i',time()+3600) ?>"></label><label>Bitiş<input type="datetime-local" name="end_at"></label><label>Müşteri<select name="customer_id"><option value="0">Seçilmedi</option><?php foreach($customers as $c): ?><option value="<?= (int)$c['id'] ?>"><?= kd_e($c['name']) ?></option><?php endforeach; ?></select></label><label>Atanan personel<select name="assigned_user_id"><option value="0">Atanmamış</option><?php foreach($users as $u): ?><option value="<?= (int)$u['id'] ?>"><?= kd_e($u['name']) ?></option><?php endforeach; ?></select></label><label>Konum<input name="location"></label><label>Hatırlatma<select name="reminder_minutes"><option value="0">Kapalı</option><option value="5">5 dakika önce</option><option value="15" selected>15 dakika önce</option><option value="30">30 dakika önce</option><option value="60">1 saat önce</option><option value="1440">1 gün önce</option></select></label><label>Açıklama<textarea name="description" rows="3"></textarea></label><button class="btn primary">Etkinlik ekle</button></form></section>
<section class="panel customer-list-panel"><div class="panel-head"><h3><?= kd_e(date('F Y',strtotime($first))) ?> etkinlikleri</h3><span class="result-count"><?= count($events) ?> kayıt</span></div><form class="filter-bar"><input type="hidden" name="page" value="calendar"><input type="month" name="month" value="<?= kd_e($month) ?>"><button class="btn secondary">Göster</button></form><div class="calendar-agenda"><?php foreach($events as $e): ?><article class="calendar-event"><div class="calendar-event-date"><strong><?= kd_e(date('d',strtotime($e['start_at']))) ?></strong><small><?= kd_e(date('H:i',strtotime($e['start_at']))) ?></small></div><div class="calendar-event-info"><strong><?= kd_e($e['title']) ?></strong><span><?= kd_e($e['event_type']) ?> · <?= kd_e($e['customer_name']??'Müşteri yok') ?> · <?= kd_e($e['assignee_name']??'Atanmamış') ?></span><?php if($e['location']): ?><small><?= kd_e($e['location']) ?></small><?php endif; ?></div><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="cancel"><input type="hidden" name="event_id" value="<?= (int)$e['id'] ?>"><button class="btn secondary">İptal</button></form></article><?php endforeach; ?><?php if(!$events): ?><p class="muted">Bu ay için planlanmış etkinlik yok.</p><?php endif; ?></div></section></div>
